export function digitClass(lo, hi) {
  if (lo > hi) throw new RangeError(...);
  if (lo === hi) return String(lo);
  return `[${lo}-${hi}]`;
}

function buildSameLength(low, high) {
  if (low.length === 0) return [''];
  const l0 = Number(low[0]);
  const h0 = Number(high[0]);
  if (l0 === h0) {
    return buildSameLength(low.slice(1), high.slice(1)).map(s => l0 + s);
  }
  const restLen = low.length - 1;
  const patterns = [];
  const anySuffix = restLen === 0 ? '' : restLen === 1 ? '[0-9]' : `[0-9]{${restLen}}`;
  // branch starting with l0
  patterns.push(...buildSameLength(low.slice(1), '9'.repeat(restLen)).map(s => l0 + s));
  // branch starting with h0
  patterns.push(...buildSameLength('0'.repeat(restLen), high.slice(1)).map(s => h0 + s));
  if (h0 - l0 >= 2) {
    patterns.push(digitClass(l0 + 1, h0 - 1) + anySuffix);
  }
  return patterns;
}
```

